def main(data: str) -> dict:
    import json
    import re
    from datetime import datetime

    errors = []
    warnings = []
    empty_result = {
        "parsed_data": {},
        "task_ctx": {},
        "overall_data": {},
        "activity_data": [],
        "is_valid": False,
        "error_list": errors,
        "warn_list": warnings
    }

    try:
        if isinstance(data, dict):
            parsed = data
        elif isinstance(data, str) and data.strip():
            parsed = json.loads(data)
        else:
            raise ValueError("data必须是非空JSON字符串")
        if not isinstance(parsed, dict):
            raise TypeError("data解析结果必须是Object")
    except Exception as exc:
        errors.append(f"JSON解析失败：{exc}")
        return empty_result

    chinese_re = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]")
    english_re = re.compile(r"[A-Za-z]")

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    def validate_tree(value, path="根"):
        if isinstance(value, dict):
            if not value:
                errors.append(f"空对象应省略：{path}")
                return
            for key, child in value.items():
                key_path = f"{path}.{key}"
                if not chinese_re.search(str(key)):
                    errors.append(f"键名必须包含中文：{key_path}")
                if english_re.search(str(key)):
                    errors.append(f"键名不得包含英文字母：{key_path}")
                validate_tree(child, key_path)
        elif isinstance(value, list):
            if not value:
                errors.append(f"空数组应省略：{path}")
                return
            for index, child in enumerate(value):
                validate_tree(child, f"{path}[{index}]")
        elif value is None:
            errors.append(f"null字段应省略：{path}")
        elif isinstance(value, str) and not value.strip():
            errors.append(f"空字符串字段应省略：{path}")

    def parse_date(value, path, with_time=False):
        if not isinstance(value, str):
            errors.append(f"{path}必须是日期字符")
            return None
        fmt = "%Y-%m-%d %H:%M:%S" if with_time else "%Y-%m-%d"
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            errors.append(f"{path}格式错误")
            return None

    validate_tree(parsed)
    for group in ["任务信息", "总体客流数据", "重点活动数据"]:
        if group not in parsed:
            errors.append(f"缺少顶层数据组：{group}")

    task = parsed.get("任务信息", {})
    for field in ["任务名称", "报告类型", "数据性质", "统计开始日期", "统计结束日期", "对比周期类型", "数据截止时间"]:
        if field not in task:
            errors.append(f"任务信息缺少字段：{field}")
    start = parse_date(task.get("统计开始日期"), "任务信息.统计开始日期")
    end = parse_date(task.get("统计结束日期"), "任务信息.统计结束日期")
    parse_date(task.get("数据截止时间"), "任务信息.数据截止时间", True)
    if start and end and start > end:
        errors.append("统计开始日期不能晚于统计结束日期")

    overall = parsed.get("总体客流数据", {})
    overall_fields = [
        "客流单位", "线网日均客运量", "线网日均客运量较对比期变化率",
        "地铁干线日均客运量", "地铁干线工作日日均客运量",
        "地铁干线非工作日日均客运量", "市域快轨日均客运量",
        "市域快轨工作日日均客运量", "市域快轨非工作日日均客运量"
    ]
    for field in overall_fields:
        if field not in overall:
            errors.append(f"总体客流数据缺少字段：{field}")
    for field in [x for x in overall_fields if x not in ["客流单位", "线网日均客运量较对比期变化率"]]:
        if not is_number(overall.get(field)) or overall.get(field) < 0:
            errors.append(f"总体客流数据.{field}必须是非负数")
    if not is_number(overall.get("线网日均客运量较对比期变化率")):
        errors.append("线网日均客运量较对比期变化率必须是数字")

    closure_fields = ["线网日均客运量", "地铁干线日均客运量", "市域快轨日均客运量"]
    if all(is_number(overall.get(x)) for x in closure_fields):
        line_sum = overall["地铁干线日均客运量"] + overall["市域快轨日均客运量"]
        if abs(line_sum - overall["线网日均客运量"]) > 0.01:
            errors.append("地铁干线日均与市域快轨日均之和不等于线网日均")

    activities = parsed.get("重点活动数据", [])
    activity_ids = [x.get("活动编号") for x in activities if isinstance(x, dict)]
    if len(activity_ids) != len(set(activity_ids)) or any(not x for x in activity_ids):
        errors.append("活动编号必须非空且唯一")
    for index, activity in enumerate(activities):
        if not isinstance(activity, dict):
            errors.append(f"重点活动数据[{index}]必须是Object")
            continue
        for field in ["活动编号", "活动名称", "活动类型", "开始日期", "结束日期", "活动地址", "影响线路", "重点车站"]:
            if field not in activity:
                errors.append(f"活动{activity.get('活动编号', index)}缺少字段：{field}")
        activity_start = parse_date(activity.get("开始日期"), f"重点活动数据[{index}].开始日期")
        activity_end = parse_date(activity.get("结束日期"), f"重点活动数据[{index}].结束日期")
        if activity_start and activity_end and activity_start > activity_end:
            errors.append(f"活动{activity.get('活动编号', index)}开始日期晚于结束日期")
        share = activity.get("活动地铁分担率")
        if share is not None and (not is_number(share) or not 0 <= share <= 100):
            errors.append(f"活动{activity.get('活动编号', index)}地铁分担率必须在0—100之间")
        for row_index, row in enumerate(activity.get("车站客流数据", [])):
            if not isinstance(row, dict):
                errors.append(f"活动{activity.get('活动编号', index)}车站客流数据[{row_index}]必须是Object")
                continue
            for field in ["进站量", "出站量"]:
                if not is_number(row.get(field)) or row.get(field) < 0:
                    errors.append(f"活动{activity.get('活动编号', index)}.{field}必须是非负数")

    return {
        "parsed_data": parsed,
        "task_ctx": task,
        "overall_data": overall,
        "activity_data": activities,
        "is_valid": len(errors) == 0,
        "error_list": errors,
        "warn_list": warnings
    }

def main(task_ctx: dict, overall_data: dict, activity_data: list[dict]) -> dict:
    import json

    packet = {
        "任务范围": {
            "统计开始日期": task_ctx["统计开始日期"],
            "统计结束日期": task_ctx["统计结束日期"],
            "对比周期类型": task_ctx["对比周期类型"]
        },
        "总体客流数据": overall_data,
        "重点活动数据": activity_data[:10]
    }
    packet["序列化字符数"] = len(json.dumps(packet, ensure_ascii=False))

    evidence = [{
        "证据编号": "E-OVERALL-001",
        "专题": "总体客流",
        "优先级": 3,
        "事实": overall_data
    }]
    for index, activity in enumerate(activity_data[:10], 1):
        evidence.append({
            "证据编号": f"E-ACT-{index:03d}",
            "专题": "重点活动",
            "优先级": 2,
            "事实": activity
        })

    return {
        "model_packet": packet,
        "evidence_pool": evidence[:12]
    }

